function drawWeather(){if(weather==='sunny'){const g=X.createLinearGradient(0,0,W,H);g.addColorStop(0,'#ead49a15');g.addColorStop(.55,'transparent');X.fillStyle=g;X.fillRect(0,0,W,H)}if(weather==='cloudy'||weather==='rain'||weather==='storm'){const drift=(time*11)%1500,g=X.createRadialGradient(drift-220,170,20,drift-220,170,420);g.addColorStop(0,weather==='storm'?'#27322d66':'#26322842');g.addColorStop(1,'transparent');X.fillStyle=g;X.fillRect(0,0,W,H)}if(state.settings.weatherFx&&(weather==='rain'||weather==='storm')){const count=weather==='storm'?75:34;X.lineCap='round';for(let i=0;i<count;i++){const depth=.35+((i*37)%65)/100,x=(i*137+time*(230+depth*260))%(W+80)-40,y=(i*83+time*(360+depth*410))%(H+60)-30;X.strokeStyle=`rgba(185,205,200,${.08+depth*.22})`;X.lineWidth=depth*1.4;X.beginPath();X.moveTo(x,y);X.lineTo(x-4*depth,y+11*depth);X.stroke();if(y>H-45&&i%6===0){X.strokeStyle='#c1d1cb45';X.beginPath();X.ellipse(x,y,7*depth,2*depth,0,0,7);X.stroke()}}}if(weather==='storm'&&Math.sin(time*3.7)>.992){X.fillStyle='#dce6df52';X.fillRect(0,0,W,H)}}
