function objectiveDone(i){if(state.quest===3)return i===0?state.inventory.berry>=5:state.inventory.ore>=3;if(state.quest===10)return state.inventory.flower>=6;if(state.quest===14)return i===0?state.inventory.ore>=5:state.inventory.scrap>=3;if(state.quest===21)return i===0?state.inventory.wood>=3:state.inventory.mushroom>=4;return state.quest===8}
function updateUI(){ui.hp.style.width=100*state.hp/state.maxHp+'%';ui.hpText.value=Math.ceil(state.hp)+' / '+state.maxHp;const prev=45*(state.level-1)*(state.level-1),next=45*state.level*state.level;ui.xp.style.width=100*(state.xp-prev)/(next-prev)+'%';ui.xpText.value=state.xp+' / '+next;ui.level.textContent=state.level;ui.coins.textContent='● '+state.inventory.coin;const keys=Object.keys(items).filter(k=>(state.inventory[k]||0)>0),slots=20;ui.inventory.innerHTML=Array.from({length:slots},(_,i)=>{const k=keys[i];if(!k)return'<div class="slot"></div>';const d=items[k],n=state.inventory[k]||0;return`<button class="slot ${selectedItem===k?'selected':''} ${state.weapon===k?'equipped':''}" data-item="${k}" aria-label="${d.name}: ${n}">${d.icon}${n>1?`<small>${n}</small>`:''}${d.rare?'<i class="rare"></i>':''}</button>`}).join('');ui.inventory.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>selectItem(b.dataset.item));ui.skills.innerHTML=Object.entries(state.skills).map(([k,v])=>{const l=1+Math.floor(Math.sqrt(v/25)),a=25*(l-1)*(l-1),z=25*l*l;return`<div class="skill-row"><div><span>${skillNames[k]}</span><b>${l}. raven</b></div><div class="mini-meter"><i style="width:${100*(v-a)/(z-a)}%"></i></div></div>`}).join('');const q=quests[state.quest]||quests[25];let objectives=q[2];if(state.quest===3)objectives=[`Zberi 5 mrakovih jagod (${Math.min(5,state.inventory.berry)}/5)`,`Izkoplji 3 rude (${Math.min(3,state.inventory.ore)}/3)`];if(state.quest===10)objectives=[`Naberi 6 mesečnic (${Math.min(6,state.inventory.flower)}/6)`];if(state.quest===14)objectives=[`Zberi 5 rud (${Math.min(5,state.inventory.ore)}/5)`,`Zberi 3 zaponke (${Math.min(3,state.inventory.scrap)}/3)`];if(state.quest===21)objectives=[`Zberi 3 polena (${Math.min(3,state.inventory.wood)}/3)`,`Zberi 4 gobe (${Math.min(4,state.inventory.mushroom)}/4)`];ui.qTitle.textContent=q[0];ui.qText.textContent=q[1];ui.objectives.innerHTML=objectives.map((o,i)=>`<div class="objective ${objectiveDone(i)?'done':(!objectiveDone(0)&&i===0)||(objectiveDone(0)&&i===1)?'active':''}">${o}</div>`).join('');if(selectedItem&&state.inventory[selectedItem])selectItem(selectedItem,true)}
function selectItem(k,quiet=false){selectedItem=k;const d=items[k],n=state.inventory[k]||0,canEquip=d.weapon&&state.level>=d.level;ui.detail.innerHTML=`${d.use&&n?'<button id="useItem">Uporabi</button>':''}${d.weapon?`<button id="equipItem">${state.weapon===k?'Opremljeno':canEquip?'Opremi':'Raven '+d.level}</button>`:''}<span>${d.name} · ${n}</span><small>${d.desc}</small>`;if(d.use&&n)$('useItem').onclick=useMushroom;if(d.weapon)$('equipItem').onclick=()=>{if(!canEquip){notify('Potrebuješ '+d.level+'. bojno raven.');return}state.weapon=k;A.play('ui');notify('Opremljeno: '+d.name);updateUI();save()};if(!quiet)updateUI()}
function drawMap(){const w=MC.width,h=MC.height,sx=w/WW,sy=h/WH;MX.fillStyle='#b7a674';MX.fillRect(0,0,w,h);for(let y=0;y<WH;y+=2)for(let x=0;x<WW;x+=2){const b=biomeAt(x*T,y*T);MX.fillStyle=waterTile(x,y)?'#527b78':b==='mountain'?'#777a6c':b==='marsh'?'#53664d':b==='goblin'?'#777245':b==='ruins'?'#5f6656':'#617b4f';MX.fillRect(x*sx,y*sy,2*sx+1,2*sy+1)}MX.fillStyle='#9b865d';for(let y=0;y<WH;y++)for(let x=0;x<WW;x++)if(pathTile(x,y))MX.fillRect(x*sx,y*sy,Math.max(1,sx),Math.max(1,sy));for(const l of landmarks){MX.fillStyle=l.type==='danger'?'#923e38':'#754c31';MX.fillRect(l.x*sx-3,l.y*sy-3,7,7);MX.fillStyle='#302a22';MX.font='10px Georgia';MX.fillText(l.name,l.x*sx+6,l.y*sy+3)}const g=questTarget();MX.fillStyle='#e4bd52';MX.beginPath();MX.arc(g.x/T*sx,g.y/T*sy,6+Math.sin(time*4),0,7);MX.fill();MX.fillStyle='#f5f0dd';MX.beginPath();MX.arc(state.x/T*sx,state.y/T*sy,5,0,7);MX.fill()}
function drawMinimap(){const w=MMC.width,h=MMC.height,cx=w/2,cy=h/2,scale=7,range=14,ptx=state.x/T,pty=state.y/T;MMX.clearRect(0,0,w,h);MMX.save();MMX.beginPath();MMX.arc(cx,cy,88,0,Math.PI*2);MMX.clip();MMX.fillStyle='#536b48';MMX.fillRect(0,0,w,h);if(state.scene==='world'){for(let ty=Math.floor(pty-range);ty<=Math.ceil(pty+range);ty++)for(let tx=Math.floor(ptx-range);tx<=Math.ceil(ptx+range);tx++){const px=cx+(tx-ptx)*scale,py=cy+(ty-pty)*scale,b=biomeAt(tx*T,ty*T);MMX.fillStyle=waterTile(tx,ty)?'#4d7777':pathTile(tx,ty)?'#9a8966':b==='mountain'?'#74786a':b==='marsh'?'#51644d':b==='goblin'?'#747044':b==='ruins'?'#606557':'#587448';MMX.fillRect(px-1,py-1,scale+1,scale+1)}for(const hse of cityPlots){const px=cx+(hse[0]-ptx)*scale,py=cy+(hse[1]-pty)*scale;if(Math.hypot(px-cx,py-cy)<83){MMX.fillStyle='#6d432e';MMX.fillRect(px-3,py-4,7,7)}}for(const n of npcs){const px=cx+(n.x/T-ptx)*scale,py=cy+(n.y/T-pty)*scale;if(Math.hypot(px-cx,py-cy)<82){MMX.fillStyle='#e6d8a8';MMX.fillRect(px-1.5,py-1.5,3,3)}}for(const e of enemies){if(e.dead)continue;const px=cx+(e.x/T-ptx)*scale,py=cy+(e.y/T-pty)*scale;if(Math.hypot(px-cx,py-cy)<82){MMX.fillStyle='#a94b42';MMX.beginPath();MMX.arc(px,py,2.2,0,7);MMX.fill()}}const g=questTarget(),gx=cx+(g.x/T-ptx)*scale,gy=cy+(g.y/T-pty)*scale;if(Math.hypot(gx-cx,gy-cy)<80){MMX.strokeStyle='#f1cb61';MMX.lineWidth=2;MMX.beginPath();MMX.arc(gx,gy,4+Math.sin(time*4),0,7);MMX.stroke()}}else{MMX.fillStyle='#3e463c';MMX.fillRect(0,0,w,h);MMX.fillStyle='#aa986c';MMX.font='12px Georgia';MMX.textAlign='center';MMX.fillText('notranjost',cx,cy-18)}MMX.translate(cx,cy);MMX.rotate(({up:0,right:Math.PI/2,down:Math.PI,left:-Math.PI/2}[state.dir]||0));MMX.fillStyle='#f5e6ad';MMX.strokeStyle='#2b2417';MMX.lineWidth=2;MMX.beginPath();MMX.moveTo(0,-8);MMX.lineTo(6,7);MMX.lineTo(0,4);MMX.lineTo(-6,7);MMX.closePath();MMX.fill();MMX.stroke();MMX.restore();$('minimapName').textContent=state.scene==='world'?locationAt(ptx,pty,currentRegion):'Notranjost'}
function toggleMap(){mapOpen=!mapOpen;ui.map.classList.toggle('hidden',!mapOpen);A.play('ui');if(mapOpen)drawMap()}
function drawDrop(o){if(o.taken||o.scene!==state.scene||!visible(o.x,o.y,50))return;const x=sx(o.x),y=sy(o.y)+Math.sin(time*3+o.bob)*2;X.fillStyle='#f0d47755';X.beginPath();X.ellipse(x,y+5,14,6,0,0,7);X.fill();X.font='17px sans-serif';X.textAlign='center';X.fillText(items[o.item].icon,x,y);if(o.n>1){X.fillStyle='#fff1ba';X.font='9px Georgia';X.fillText('×'+o.n,x+11,y+7)}}
function drawMazeEntrance(){const p=portals.find(v=>v.id==='shadowMaze'),x=sx(p.x),y=sy(p.y);if(!visible(p.x,p.y,90))return;shadow(p.x,p.y,32);X.fillStyle='#4b5148';X.beginPath();X.ellipse(x,y-4,34,31,0,Math.PI,0);X.lineTo(x+34,y+13);X.lineTo(x-34,y+13);X.fill();X.fillStyle='#171c1b';X.beginPath();X.ellipse(x,y+5,20,24,0,Math.PI,0);X.lineTo(x+20,y+14);X.lineTo(x-20,y+14);X.fill();X.strokeStyle='#9a8650';X.lineWidth=2;X.beginPath();X.arc(x,y+1,27,Math.PI,Math.PI*2);X.stroke();X.fillStyle='#d6b954';X.font='10px Georgia';X.textAlign='center';X.fillText('III',x,y-26)}
