const speakBase=speak;speak=function(name,lines,end){const who={Mira:'Miroslava',Iva:'Živana','General Grub':'Vojvoda Gromobor','General Nib':'Vojvoda Črnomir','Kovač Bor':'Kovač Borislav','Mlinar Jure':'Mlinar Jaromir'}[name]||name;speakBase(who,lines.map(v=>v.replaceAll('Arin','Kresnik').replaceAll('Grub','Gromobor').replaceAll('Nib','Črnomir')),end)};
const renameLore=s=>s.replaceAll('Mira','Miroslava').replaceAll('Grub','Gromobor').replaceAll('Nib','Črnomir').replaceAll('kovača Bora','kovača Borislava').replaceAll('kovaču Boru','kovaču Borislavu').replaceAll('Mlinar Jure','Mlinar Jaromir').replaceAll('mlinarja Jureta','mlinarja Jaromira').replaceAll('mlinarju Juretu','mlinarju Jaromiru');for(const q of Object.values(quests)){q[1]=renameLore(q[1]);q[2]=q[2].map(renameLore)}
const questTargetBase=questTarget;questTarget=function(){const q=questTargetBase();q.label=q.label.replace('Miro','Miroslavo').replace('generala Gruba','vojvodo Gromobora').replace('generala Niba','vojvodo Črnomira').replace('kovača Bora','kovača Borislava').replace('kovaču Boru','kovaču Borislavu').replace('mlinarja Jureta','mlinarja Jaromira');return q};
function dropLoot(e){const drops=[{item:'bones',n:1},{item:'coin',n:e.type==='boss'?18:2+Math.floor(Math.random()*5)}];if(e.type==='goblin'&&Math.random()<.45)drops.push({item:Math.random()<.18?'ironScimitar':'scrap',n:1});if(e.type==='wolf'&&Math.random()<.55)drops.push({item:'hide',n:1});if(Math.random()<.28)drops.push({item:'bread',n:1});drops.forEach((d,i)=>loot.push({id:e.id+'_'+i,item:d.item,n:d.n,x:e.x+(i-1)*15,y:e.y+8+Math.abs(i-1)*8,scene:state.scene,bob:Math.random()*6.28}))}
function pickupLoot(o){state.inventory[o.item]=(state.inventory[o.item]||0)+o.n;o.taken=true;A.play('pickup');floatText('+'+o.n+' '+items[o.item].name,o.x,o.y-18);updateUI();save()}
kill=function(e){e.dead=true;gain('combat',e.type==='boss'?55:e.type==='goblin'?12:e.type==='wolf'?10:7);dropLoot(e);if(e.id==='boglug'){state.bossDead=true;setQuest(7,'Boglug je premagan. Vrni se k Miri.')}if(e.id==='gromovnik'){state.stormDead=true;setQuest(19,'Gromovnik je premagan. Vrni se k Radovanu.')}if(e.id==='povodni'){state.waterDead=true;state.inventory.waterPearl=1;setQuest(24,'Prejel si biser. Vrni se k mlinarju Juretu.')}A.play('quest');emit(e.x,e.y,'#edc568',e.type==='boss'?45:12)};
const buildBaseWorld=buildWorld;buildWorld=function(){buildBaseWorld();const maze=portals.find(p=>p.id==='shadowMaze');for(let i=resources.length-1;i>=0;i--)if(exploreSites.some(o=>Math.hypot(o.x-resources[i].x,o.y-resources[i].y)<48)||Math.hypot(maze.x-resources[i].x,maze.y-resources[i].y)<70)resources.splice(i,1)};
const nearestBase=nearest;nearest=function(){nearestBase();for(const o of loot){if(o.taken||o.scene!==state.scene)continue;const q=Math.hypot(o.x-state.x,o.y-state.y);if(q<44){target={kind:'loot',o,label:'Poberi: '+items[o.item].name};ui.prompt.classList.add('show');ui.prompt.innerHTML='<b>E</b> · '+target.label;break}}};
const interactBase=interact;interact=function(){if(target?.kind==='loot'){A.init();pickupLoot(target.o);target=null;return}interactBase()};
const solidBase=solidAt;solidAt=function(x,y,r=10){if(state.scene!=='shadowMaze')return solidBase(x,y,r);if(x<56||x>W-56||y<82||y>H-55)return true;for(const q of[[320,82,24,278],[320,430,24,115],[480,230,24,315],[650,82,24,278],[650,430,24,115]])if(x+r>q[0]&&x-r<q[0]+q[2]&&y+r>q[1]&&y-r<q[1]+q[3])return true;return false};
const interiorBase=drawInteriorDetails;drawInteriorDetails=function(){interiorBase();if(state.scene!=='shadowMaze')return;X.fillStyle='#141817';X.fillRect(0,72,W,H-122);X.fillStyle='#3f4742';for(let y=82;y<H-50;y+=32)for(let x=56;x<W-56;x+=32){X.fillStyle=(x+y)%64?'#3b433e':'#444b44';X.fillRect(x,y,30,30)}X.fillStyle='#171b19';for(const q of[[320,82,24,278],[320,430,24,115],[480,230,24,315],[650,82,24,278],[650,430,24,115]]){X.fillRect(q[0],q[1],q[2],q[3]);X.strokeStyle='#697067';X.strokeRect(q[0],q[1],q[2],q[3])}X.fillStyle='#9b7936';X.fillRect(W/2+115,H/2-15,40,30);X.fillStyle='#efcb55';X.fillRect(W/2+130,H/2-15,6,30)};
const chestBase=openChest;openChest=function(){if(state.scene!=='shadowMaze'){chestBase();return}if(state.chests.shadowMaze){notify('Zlata skrinja je prazna.');return}state.chests.shadowMaze=true;state.inventory.goldScimitar=1;state.inventory.sunShield=1;gain('combat',80);gain('defence',80);A.play('quest');speak('Skrinja kralja Samota',['V zlati skrinji počivata ukrivljeno rezilo in ščit s tremi sonci.','DOBIL SI: Zlati krivec kralja Samota, Ščit treh sonc, 80 bojnih EXP in 80 obrambnih EXP.'],()=>{updateUI();save()})};
function useInventoryItem(k){if(!state.inventory[k])return;if(k==='bones'){state.inventory[k]--;gain('spirit',12);A.play('quest');notify('Kosti si položil v zemljo. +12 izročila.')}else if(k==='bread'){if(state.hp>=state.maxHp)return;state.inventory[k]--;state.hp=Math.min(state.maxHp,state.hp+22);A.play('heal');notify('Kruh ti povrne 22 življenja.')}else useMushroom();updateUI();save()}
selectItem=function(k,quiet=false){selectedItem=k;const d=items[k],n=state.inventory[k]||0,canEquip=d.weapon&&state.level>=d.level,equipped=state.weapon===k||state.armor===k||state.shield===k;ui.detail.innerHTML=`${d.use&&n?'<button id="useItem">Uporabi</button>':''}${d.weapon?`<button id="equipItem">${state.weapon===k?'Opremljeno':canEquip?'Opremi':'Raven '+d.level}</button>`:''}${d.armor?`<button id="equipItem">${equipped?'Opremljeno':'Opremi'}</button>`:''}<span>${d.name} · ${n}</span><small>${d.desc}</small>`;if(d.use&&n)$('useItem').onclick=()=>useInventoryItem(k);if(d.weapon||d.armor)$('equipItem').onclick=()=>{if(d.weapon&&!canEquip){notify('Potrebuješ '+d.level+'. bojno raven.');return}if(d.weapon)state.weapon=k;else if(k==='sunShield')state.shield=k;else state.armor=k;A.play('ui');notify('Opremljeno: '+d.name);updateUI();save()};if(!quiet)updateUI()};
hurt=function(n){if(player.invuln||state.hp<=0)return;const guard=(items[state.armor]?.armor||0)+(items[state.shield]?.armor||0),damage=Math.max(1,n-guard);state.hp-=damage;gain('defence',2);player.invuln=.85;shake=8;A.play('hurt');floatText('-'+damage,state.x,state.y-28,'#ff8478');if(state.hp<=0){state.hp=0;ui.death.classList.remove('hidden')}updateUI()};
const drawBaseMinimap=drawMinimap;drawMinimap=function(){drawBaseMinimap();if(state.scene!=='world')return;const cx=MMC.width/2,cy=MMC.height/2,ptx=state.x/T,pty=state.y/T;MMX.save();for(const o of exploreSites){const x=cx+(o.x/T-ptx)*7,y=cy+(o.y/T-pty)*7;if(Math.hypot(x-cx,y-cy)>78)continue;MMX.fillStyle=state.discoveries[o.id]?'#8d8060':'#f0cf67';MMX.beginPath();MMX.moveTo(x,y-3);MMX.lineTo(x+3,y);MMX.lineTo(x,y+3);MMX.lineTo(x-3,y);MMX.closePath();MMX.fill()}MMX.restore()};
$('minimapOpen').onclick=toggleMap;
function loop(now){const dt=Math.min(.033,(now-last)/1000);last=now;update(dt);drawWorld();drawMinimap();if(mapOpen)drawMap();requestAnimationFrame(loop)}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','e',' ','1','m','escape'].includes(k))e.preventDefault();A.init();if(!e.repeat){if(k==='e')interact();if(k===' ')attack();if(k==='1')useMushroom();if(k==='m'&&!menuOpen)toggleMap();if(k==='escape')toggleMenu()}keys[k]=true});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function toggleMenu(force){menuOpen=force===undefined?!menuOpen:force;$('mainMenu').classList.toggle('hidden',!menuOpen);if(menuOpen){renderSlots();save()}A.play('ui')}
function startNew(){if(localStorage.getItem('mah-save-current')&&!confirm('Začnem novo zgodbo? Trenutno igro lahko prej shraniš v režo.'))return;localStorage.removeItem('mah-save-current');hydrate(null);resources.length=enemies.length=fireflies.length=clouds.length=0;buildWorld();updateUI();toggleMenu(false);transitionTip()}
function showMenuPanel(kind){const p=$('menuPanel');$('saveSlots').classList.add('hidden');p.classList.remove('hidden');if(kind==='settings'){p.innerHTML=`<h3>Nastavitve in kontrole</h3><label>Polni vremenski učinki <input id="weatherSetting" type="checkbox" ${state.settings.weatherFx?'checked':''}></label><label>Tresenje zaslona <input id="shakeSetting" type="checkbox" ${state.settings.screenShake?'checked':''}></label><p><kbd>WASD</kbd> ali puščice — premik<br><kbd>E</kbd> — pogovor, vrata in nabiranje<br><kbd>Space</kbd> — hiter zaporedni napad<br><kbd>M</kbd> — zemljevid · <kbd>1</kbd> — zaužij gobo · <kbd>Esc</kbd> — meni</p><button id="panelClose">Zapri</button>`;$('weatherSetting').onchange=e=>{state.settings.weatherFx=e.target.checked;save()};$('shakeSetting').onchange=e=>{state.settings.screenShake=e.target.checked;save()}}else p.innerHTML='<h3>Zasluge</h3><p>Zasnova, svet in izvedba: Mah in žerjavica.<br>Izvirni svet temelji na slovenskem pripovednem izročilu. Vizualni elementi so bili ustvarjeni posebej za projekt. Glasbene datoteke in licence so navedene v assets/audio/CREDITS.md.</p><p>Navdih: počasno raziskovanje starih računalniških RPG-jev, slovenska krajina in ljudske pripovedke. Nobena mapa, melodija ali lik ni kopija druge igre.</p><button id="panelClose">Zapri</button>';$('panelClose').onclick=()=>p.classList.add('hidden');A.play('ui')}
document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button,.tab-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.tab).classList.add('active');A.play('ui')});document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.onpointerdown=e=>{e.preventDefault();A.init();keys[k]=true};b.onpointerup=b.onpointercancel=b.onpointerleave=()=>keys[k]=false});document.querySelector('[data-tap="interact"]').onclick=interact;document.querySelector('[data-tap="attack"]').onclick=attack;$('mapBtn').onclick=$('closeMap').onclick=toggleMap;$('soundBtn').onclick=()=>{$('soundBtn').textContent=A.toggle()?'♫':'♩'};$('menuBtn').onclick=()=>toggleMenu();$('continueBtn').onclick=()=>toggleMenu(false);$('loadBtn').onclick=()=>{$('saveSlots').classList.toggle('hidden');renderSlots()};$('menuNewBtn').onclick=startNew;$('rewardBtn').onclick=()=>ui.questReward.classList.add('hidden');$('wakeBtn').onclick=()=>{state.hp=state.maxHp;state.scene='world';state.x=camp.x;state.y=camp.y;ui.death.classList.add('hidden');updateUI();save()};addEventListener('beforeunload',save);
